mapper.select:
SELECT a.*, CASE WHEN a.type = 'RESOURCE' THEN r.name WHEN a.type = 'VENUE' THEN f.name END AS resourceName, u.nickname AS userName FROM appointment AS a LEFT JOIN resource AS r ON a.type = 'RESOURCE' AND r.id = a.resource_id LEFT JOIN facility AS f ON a.type = 'VENUE' AND f.id = a.resource_id LEFT JOIN user AS u ON u.id = a.user_id
AND a.status = #{status}
AND a.type = #{type}
AND a.appoint_date >= #{beginDate}
AND a.appoint_date <= #{endDate}
ORDER BY a.create_time DESC
